    func test_nan_inf() {
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.sum(x), MfArray([.nan] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.mean(x), MfArray([.nan] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.squaresum(x), MfArray([.nan] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.squaresum(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.cumsum(x), MfArray([1.0, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan] as [Double], mftype: .Double, shape: [12]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(x) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.sum(x, axis: 0), MfArray([.nan, .nan, .nan, 7.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(x, axis: 0) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.mean(x, axis: 0), MfArray([.nan, .nan, .nan, 2.3333333333333335] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(x, axis: 0) \(name)")
        }
        for (name, x) in layoutVariants(AN){
            XCTAssertClose(Matft.stats.squaresum(x, axis: 0), MfArray([.nan, .nan, .nan, 21.0] as [Double], mftype: .Double, shape: [4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.squaresum(x, axis: 0) \(name)")
        }
