    func test_integer_wrap() {
        XCTAssertClose(Matft.stats.sum(MfArray([200, 100, 250] as [Int], mftype: .UInt8)), MfArray([38] as [Int], mftype: .UInt8, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([200, 100, 250] as [Int], mftype: .UInt8))")
        XCTAssertClose(Matft.stats.sum(MfArray([127, 1] as [Int], mftype: .Int8)), MfArray([-128] as [Int], mftype: .Int8, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([127, 1] as [Int], mftype: .Int8))")
        XCTAssertClose(Matft.stats.cumsum(MfArray([200, 100, 250] as [Int], mftype: .UInt8)), MfArray([200, 44, 38] as [Int], mftype: .UInt8, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(MfArray([200, 100, 250] as [Int], mftype: .UInt8))")
        XCTAssertClose(Matft.stats.cumsum(MfArray([-100, -100, 50] as [Int], mftype: .Int8)), MfArray([-100, 56, 106] as [Int], mftype: .Int8, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(MfArray([-100, -100, 50] as [Int], mftype: .Int8))")
        XCTAssertClose(Matft.ufuncReduce(mfarray: MfArray([16, 16, 3] as [Int], mftype: .UInt8), ufunc: Matft.mul), MfArray([0] as [Int], mftype: .UInt8, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.ufuncReduce(mfarray: MfArray([16, 16, 3] as [Int], mftype: .UInt8), ufunc: Matft.mul)")
    }

    func test_empty() {
        XCTAssertClose(Matft.stats.sum(MfArray([] as [Double], mftype: .Double, shape: [3, 0])), MfArray([0.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([] as [Double], mftype: .Double, shape: [3, 0]))")
