        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]])), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]))")
        XCTAssertClose(Matft.stats.sum(MfArray([[5.0]] as [[Double]]), keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([[5.0]] as [[Double]]), keepDims: true)")
        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]]), keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]), keepDims: true)")
        XCTAssertClose(Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 0), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 0)")
        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 0), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 0)")
        XCTAssertClose(Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 0, keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 0, keepDims: true)")
        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 0, keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 0, keepDims: true)")
        XCTAssertClose(Matft.stats.cumsum(MfArray([[5.0]] as [[Double]]), axis: 0), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(MfArray([[5.0]] as [[Double]]), axis: 0)")
        XCTAssertClose(Matft.ufuncReduce(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 0), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.ufuncReduce(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 0)")
        XCTAssertClose(Matft.ufuncAccumulate(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 0), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.ufuncAccumulate(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 0)")
        XCTAssertClose(Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 1), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 1)")
        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 1), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 1)")
        XCTAssertClose(Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 1, keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([[5.0]] as [[Double]]), axis: 1, keepDims: true)")
        XCTAssertClose(Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 1, keepDims: true), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.mean(MfArray([[5.0]] as [[Double]]), axis: 1, keepDims: true)")
        XCTAssertClose(Matft.stats.cumsum(MfArray([[5.0]] as [[Double]]), axis: 1), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(MfArray([[5.0]] as [[Double]]), axis: 1)")
        XCTAssertClose(Matft.ufuncReduce(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 1), MfArray([5.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.ufuncReduce(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 1)")
        XCTAssertClose(Matft.ufuncAccumulate(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 1), MfArray([5.0] as [Double], mftype: .Double, shape: [1, 1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.ufuncAccumulate(mfarray: MfArray([[5.0]] as [[Double]]), ufunc: Matft.add, axis: 1)")
        XCTAssertClose(Matft.stats.sum(MfArray([7.0] as [Double]), axis: 0), MfArray([7.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.sum(MfArray([7.0] as [Double]), axis: 0)")
        XCTAssertClose(Matft.stats.cumsum(MfArray([7.0] as [Double]), axis: 0), MfArray([7.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.cumsum(MfArray([7.0] as [Double]), axis: 0)")
    }

    func test_method_forms() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.sum(axis: 1), MfArray([7.0, 18.0, 21.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.sum(axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.sum(axis: 0, keepDims: true), MfArray([13.0, 11.0, 7.0, 15.0] as [Double], mftype: .Double, shape: [1, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.sum(axis: 0, keepDims: true) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.mean(axis: -1), MfArray([1.75, 4.5, 5.25] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.mean(axis: -1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.squaresum(), MfArray([296.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.squaresum() \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.sumsqrt(axis: 1), MfArray([2.6457513110645907, 4.242640687119285, 4.58257569495584] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.sumsqrt(axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.cumsum(axis: 1), MfArray([3.0, 2.0, 6.0, 7.0, 5.0, 14.0, 12.0, 18.0, 5.0, 8.0, 13.0, 21.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.cumsum(axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x.cumsum(), MfArray([3.0, 2.0, 6.0, 7.0, 12.0, 21.0, 19.0, 25.0, 30.0, 33.0, 38.0, 46.0] as [Double], mftype: .Double, shape: [12]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.cumsum() \(name)")
        }
    }

    func test_input_unchanged() {
        for (name, x) in layoutVariants(A){
            let before = rowValues(x)
            _ = Matft.stats.cumsum(x, axis: 0); _ = Matft.stats.sum(x, axis: 1); _ = Matft.stats.mean(x)
            _ = Matft.ufuncReduce(mfarray: x, ufunc: Matft.add, axis: 1); _ = Matft.ufuncAccumulate(mfarray: x, ufunc: Matft.add, axis: 1)
            XCTAssertEqual(rowValues(x), before, "input changed \(name)")
        }
    }
}
